pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 _feeRate) public {
        // The bug only triggers when _feeRate > 5000, so we restrict to the admissible domain
        // where the mutant's violation can be observed. We still let the fuzzer pick the exact value.
        vm.assume(_feeRate > 5000);

        // Any valid values for the other parameters; we pick zero-like values for simplicity.
        address base = address(0);
        address nftAddr = address(0x1);
        uint128 vBase = 0;
        uint128 vNft = 0;
        uint56 changeFee = 0;
        bytes32 root = bytes32(0);
        bool useOracle = false;
        bool payR = false;

        // In the reference contract, initialize should revert and feeRate should remain 0 (default).
        // The buggy contract sets feeRate = _feeRate before reverting, so feeRate() == _feeRate even after revert.
        bool ok1 = false;
        try c.initialize(base, nftAddr, vBase, vNft, changeFee, _feeRate, root, useOracle, payR) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // After the (likely) revert, feeRate should be 0 (default) in the correct contract.
        // The buggy version would leave it as _feeRate.
        assertTrue(!ok1 && c.feeRate() == 0);
    }
}

