import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // Keep the domain wide: any feeRate value is admissible
        // We need a feeRate that triggers the revert in the reference (>
5000)
        // but the fuzzer should also try values <= 5000 to ensure the property holds universally.
        // No vm.assume needed here.

        uint16 beforeFee = c.feeRate();
        bool reverted = false;
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            // Did not revert (this can happen if _feeRate <= 5000 and initialized is false)
        } catch {
            reverted = true;
        }
        uint16 afterFee = c.feeRate();

        // The general rule: if initialize() reverted, feeRate must be unchanged.
        // If it succeeded, feeRate must be _feeRate.
        if (reverted) {
            assertEq(afterFee, beforeFee, "feeRate changed after failed initialize");
        } else {
            assertEq(afterFee, _feeRate, "feeRate not set correctly on success");
        }
    }
}

