pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint8 _decimals) public {
        // Bound the decimals to a valid range that keeps the fee rate below the 5000 limit (default feeRate is 0).
        uint8 decimals = uint8(bound(_decimals, 1, 18));
        // Prepare initialization parameters
        address baseToken = address(0);
        address nft = address(0);
        uint128 virtualBase = 1 ether;
        uint128 virtualNft = 1 ether;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenOracle = false;
        bool payRoyalties = false;

        // First call to initialize must succeed
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolenOracle, payRoyalties);
        // A second call to initialize must revert because the reference sets initialized = true.
        // The mutant omits that assignment, so the second call succeeds.
        bool secondCallReverted;
        try c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolenOracle, payRoyalties) {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        // Generic rule: after a successful first initialization, any subsequent call to initialize must revert.
        // This holds for the reference (initialized == true) and is broken by the mutant (initialized remains false).
        assertTrue(secondCallReverted);
    }
}

